"""Resolve a named model group from a caller-supplied list."""

from __future__ import annotations

from typing import Any

from rasa.shared.constants import MODEL_GROUP_CONFIG_KEY, MODEL_GROUP_ID_CONFIG_KEY
from rasa.shared.exceptions import InvalidConfigException
from rasa.shared.utils.llm import resolve_model_client_config


def resolve_named_model_group(
    group_id: str,
    model_groups: list[dict[str, Any]],
    *,
    part: str,
) -> dict[str, Any]:
    """Resolve ``group_id`` against ``model_groups`` for ``part``.

    Args:
        group_id: Model group id from the caller. Leading and trailing
            whitespace is ignored.
        model_groups: Group definitions the caller already loaded. An empty
            list is rejected here so resolution does not fall through to
            endpoints.yml.
        part: Caller name included in failure messages.

    Returns:
        The matching group definition.

    Raises:
        InvalidConfigException: When the name is blank, no groups are
            defined, the id is unknown, or the id is declared more than once.
    """
    stripped_id = group_id.strip()
    if not stripped_id:
        raise InvalidConfigException(f"Model group name for '{part}' is blank.")
    if not model_groups:
        raise InvalidConfigException(
            f"No model groups are defined for '{part}' "
            f"(model group '{stripped_id}')."
        )

    matches = [
        group
        for group in model_groups
        if group.get(MODEL_GROUP_ID_CONFIG_KEY) == stripped_id
    ]
    if not matches:
        raise InvalidConfigException(
            f"No model group '{stripped_id}' is defined for '{part}'."
        )
    if len(matches) > 1:
        raise InvalidConfigException(
            f"Multiple model groups named '{stripped_id}' are defined for '{part}'."
        )

    resolved = resolve_model_client_config(
        {MODEL_GROUP_CONFIG_KEY: stripped_id},
        part,
        model_groups=model_groups,
    )
    # A dict with model_group set never resolves to None. None is only returned
    # when the config argument itself is None.
    return resolved  # type: ignore[return-value]
